import React, { useContext } from "react";
import { useParams } from "react-router-dom";
import { ShopContext } from "../context/ShopContext";
import Breadcrum from "../components/Breadcrums/Breadcrum";

const Product = () => {
  const { all_product } = useContext(ShopContext);
  const { productId } = useParams();

  const product = all_product.find((e) => e.id === Number(productId));

 console.log("productId from URL:", productId);
console.log("Converted productId:", Number(productId));
console.log("All Product IDs:", all_product.map((p) => p.id));


  // 🛑 If data not ready or product not found yet, show nothing or a loader
  if (!product) {
    return <div>Loading...</div>; // or custom loading UI
  }

  return (
    <div>
      <Breadcrum product={product} />
    </div>
  );
};

export default Product;
